import { test } from 'node:test';
import assert from 'node:assert/strict';
import { once } from 'node:events';
import * as z from 'node:zlib';
import { createApp, negotiate } from './server.mjs';

const decoders = { br: z.brotliDecompressSync, gzip: z.gunzipSync, zstd: z.zstdDecompressSync };

test('Accept-Encoding honors quality, exclusions, wildcard and identity', () => {
  const all = ['br', 'gzip', 'zstd', 'identity'];
  assert.equal(negotiate('br;q=0, gzip;q=1, zstd;q=.5', all), 'gzip');
  assert.equal(negotiate('br, gzip', all), 'br');
  assert.equal(negotiate('*;q=0', all), undefined);
  assert.equal(negotiate('', all), 'identity');
  assert.equal(negotiate('gzip;q=.5', all), 'identity');
  assert.equal(negotiate('zstd', ['gzip']), undefined);
});

test('uploaded wasm, round trip, encoded delivery and errors', async t => {
  const server = createApp(); server.listen(0, '127.0.0.1'); await once(server, 'listening');
  t.after(() => new Promise(resolve => server.close(resolve)));
  const base = `http://127.0.0.1:${server.address().port}`;
  const get = path => fetch(base + path);
  const original = Buffer.from('0061736d010000000105016000017f030201000707010361646400000a06010400412a0b', 'hex');
  assert.equal(WebAssembly.validate(original), true);
  const service = await (await get('/api/status')).json();
  assert.equal(service.maxBytes, null);
  assert.equal((await get('/api/samples')).status, 404);
  const bad = await fetch(base + '/api/jobs', { method: 'POST', body: 'not wasm' });
  assert.equal(bad.status, 400);
  const crossSite = await fetch(base + '/api/jobs', { method: 'POST', headers: { Origin: 'https://example.org' }, body: original });
  assert.equal(crossSite.status, 403);
  const created = await fetch(base + '/api/jobs?name=test.wasm&preset=fast', { method: 'POST', headers: { 'Content-Type': 'application/wasm' }, body: original });
  assert.equal(created.status, 202);
  let job = await created.json();
  for (let tries = 0; tries < 100 && job.status === 'running'; tries++) {
    await new Promise(resolve => setTimeout(resolve, 50));
    job = await (await get(`/api/jobs/${job.id}`)).json();
  }
  assert.equal(job.status, 'done', job.error); assert.equal(job.results.length, 3);
  for (const result of job.results) {
    assert.equal(result.verified, true);
    const download = await get(result.download);
    assert.equal(download.headers.get('content-encoding'), null);
    assert.match(download.headers.get('content-disposition'), /attachment/);
    const compressed = Buffer.from(await download.arrayBuffer());
    assert.equal(compressed.length, result.size);
    assert.deepEqual(decoders[result.encoding](compressed), original);
  }
  const delivered = await fetch(`${base}/api/jobs/${job.id}/module/auto`, { headers: { 'Accept-Encoding': 'br;q=0,gzip;q=1' } });
  assert.equal(delivered.headers.get('content-type'), 'application/wasm');
  assert.equal(delivered.headers.get('content-encoding'), 'gzip');
  assert.equal(delivered.headers.get('vary'), 'Accept-Encoding');
  assert.deepEqual(Buffer.from(await delivered.arrayBuffer()), original);
  const stream = await fetch(`${base}/api/jobs/${job.id}/module/br`, { headers: { 'Accept-Encoding': 'br' } });
  const module = await WebAssembly.compileStreaming(stream);
  assert.ok(WebAssembly.Module.exports(module).length > 0);
  assert.equal((await fetch(`${base}/api/jobs/${job.id}/module/zstd`, { headers: { 'Accept-Encoding': 'gzip' } })).status, 406);
  const upload = await fetch(base + '/api/jobs?name=uploaded.wasm&algorithms=gzip', { method: 'POST', headers: { 'Content-Type': 'application/wasm' }, body: original });
  assert.equal(upload.status, 202); let uploaded = await upload.json();
  for (let tries = 0; tries < 100 && uploaded.status === 'running'; tries++) {
    await new Promise(resolve => setTimeout(resolve, 50));
    uploaded = await (await get(`/api/jobs/${uploaded.id}`)).json();
  }
  assert.equal(uploaded.status, 'done'); assert.equal(uploaded.name, 'uploaded.wasm');
  assert.equal(uploaded.results.length, 1);
  assert.equal((await get('/server.mjs')).status, 404);

  // A custom section keeps the large fixture valid without a large executable body.
  const payloadLength = 33 * 1024 * 1024;
  const leb = [];
  for (let remaining = payloadLength; ; remaining = Math.floor(remaining / 128)) {
    const next = remaining % 128;
    leb.push(next | (remaining >= 128 ? 128 : 0));
    if (remaining < 128) break;
  }
  const large = Buffer.concat([Buffer.from('0061736d01000000', 'hex'), Buffer.from([0, ...leb]), Buffer.alloc(payloadLength)]);
  assert.equal(WebAssembly.validate(large), true);
  const largeResponse = await fetch(base + '/api/jobs?name=large.wasm&algorithms=gzip', { method: 'POST', body: large });
  assert.equal(largeResponse.status, 202);
  let largeJob = await largeResponse.json();
  for (let tries = 0; tries < 200 && largeJob.status === 'running'; tries++) {
    await new Promise(resolve => setTimeout(resolve, 50));
    largeJob = await (await get(`/api/jobs/${largeJob.id}`)).json();
  }
  assert.equal(largeJob.status, 'done', largeJob.error);
  assert.equal(largeJob.size, large.length);
  const largeDownload = await get(largeJob.results[0].download);
  assert.deepEqual(z.gunzipSync(Buffer.from(await largeDownload.arrayBuffer())), large);
});

import { parentPort, workerData } from 'node:worker_threads';
import { createHash } from 'node:crypto';
import * as z from 'node:zlib';

const input = Buffer.from(workerData.bytes);
const hash = data => createHash('sha256').update(data).digest('hex');
const digest = hash(input);
const level = workerData.preset === 'archive'
  ? { br: 11, gzip: 9, zstd: 19 }
  : { br: 5, gzip: 6, zstd: 3 };
const codecs = {
  br: [data => z.brotliCompressSync(data, { params: {
    [z.constants.BROTLI_PARAM_QUALITY]: level.br,
    [z.constants.BROTLI_PARAM_SIZE_HINT]: input.length,
  } }), z.brotliDecompressSync],
  gzip: [data => z.gzipSync(data, { level: level.gzip }), z.gunzipSync],
  zstd: [data => z.zstdCompressSync(data, { params: {
    [z.constants.ZSTD_c_compressionLevel]: level.zstd,
    [z.constants.ZSTD_c_windowLog]: 23,
  } }), z.zstdDecompressSync],
};

try {
  for (const encoding of workerData.algorithms) {
    parentPort.postMessage({ type: 'progress', encoding });
    const [compress, decompress] = codecs[encoding];
    const started = performance.now();
    const bytes = compress(input);
    const compressionMs = performance.now() - started;
    const decodeStart = performance.now();
    const decoded = decompress(bytes);
    const decompressionMs = performance.now() - decodeStart;
    if (!decoded.equals(input) || hash(decoded) !== digest) throw new Error('压缩回解校验失败');
    parentPort.postMessage({ type: 'result', encoding, bytes, level: level[encoding],
      compressionMs, decompressionMs, verified: true });
  }
  parentPort.postMessage({ type: 'done', sha256: digest });
} catch (error) {
  parentPort.postMessage({ type: 'failure', error: error.message });
}

const $ = id => document.getElementById(id);
const names = { br: 'Brotli', gzip: 'gzip', zstd: 'Zstd', identity: '原始' };
let file, job, busy = false;
const size = n => n < 1024 * 1024 ? `${(n / 1024).toFixed(1)} KiB` : `${(n / 1024 / 1024).toFixed(3)} MiB`;
const ms = n => `${n.toFixed(1)} ms`;
function status(message, error = false) { $('status').textContent = message; $('status').classList.toggle('error', error); }
function lock(locked) {
  busy = locked;
  for (const el of document.querySelectorAll('aside button, aside select, aside input')) el.disabled = locked;
  $('compress').disabled = locked || !file;
  $('compress').querySelector('span').textContent = locked ? '正在压缩…' : '开始压缩对比';
}
function chooseFile(selected) {
  if (!selected) return;
  if (!selected.name.toLowerCase().endsWith('.wasm')) { status('请选择 .wasm 文件。', true); return; }
  file = selected; $('file-info').textContent = `${file.name} · ${size(file.size)}`; lock(false); status('文件已就绪。');
}
$('file-input').onchange = e => chooseFile(e.target.files[0]);
for (const event of ['dragenter', 'dragover']) $('dropzone').addEventListener(event, e => { e.preventDefault(); if (!busy) $('dropzone').classList.add('drag'); });
for (const event of ['dragleave', 'drop']) $('dropzone').addEventListener(event, e => { e.preventDefault(); $('dropzone').classList.remove('drag'); });
$('dropzone').addEventListener('drop', e => { if (!busy) chooseFile(e.dataTransfer.files[0]); });
async function request(url, options) {
  const response = await fetch(url, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || '请求失败');
  return data;
}
function cell(row, value, className) { const td = document.createElement('td'); td.textContent = value; if (className) td.className = className; row.append(td); return td; }
function render(data) {
  $('empty').hidden = true; $('results').hidden = false;
  $('result-name').textContent = data.name; $('original-size').textContent = `原始体积 ${size(data.size)} · ${data.size.toLocaleString()} bytes`;
  $('result-state').textContent = data.status === 'done' ? '校验通过' : data.status === 'failed' ? '任务失败' : '压缩中';
  $('result-state').classList.toggle('done', data.status === 'done');
  $('chart').replaceChildren(); $('result-rows').replaceChildren();
  for (const item of [{ encoding: 'identity', size: data.size }, ...data.results]) {
    const row = document.createElement('div'); row.className = 'bar-row';
    const label = document.createElement('span'); label.textContent = names[item.encoding];
    const track = document.createElement('div'); track.className = 'bar-track';
    const bar = document.createElement('div'); bar.className = `bar ${item.encoding}`; bar.style.transform = `scaleX(${Math.min(1, item.size / data.size)})`; track.append(bar);
    const value = document.createElement('span'); value.className = 'bar-value'; value.textContent = size(item.size);
    row.append(label, track, value); $('chart').append(row);
  }
  const best = Math.min(...data.results.map(r => r.size));
  for (const r of data.results) {
    const row = document.createElement('tr');
    const first = cell(row, `${names[r.encoding]} · ${r.level}`);
    if (r.size === best && data.status === 'done') { const tag = document.createElement('small'); tag.textContent = '最小'; first.append(tag); }
    cell(row, size(r.size)); cell(row, `${(r.saving * 100).toFixed(1)}%`, 'saving'); cell(row, ms(r.compressionMs)); cell(row, ms(r.decompressionMs));
    const last = cell(row, ''); const a = document.createElement('a'); a.href = r.download; a.textContent = `下载 .${{ br: 'br', gzip: 'gz', zstd: 'zst' }[r.encoding]}`; a.setAttribute('download', ''); last.append(a);
    $('result-rows').append(row);
  }
  $('sha').textContent = data.sha256;
  $('verification').textContent = data.results.length ? `${data.results.length} 个结果已回解，原始字节与 SHA-256 一致。` : '正在生成并校验压缩结果…';
  $('export').disabled = data.status !== 'done';
}
$('compress').onclick = async () => {
  const algorithms = [...document.querySelectorAll('input[name=codec]:checked')].map(el => el.value);
  if (!algorithms.length) { status('至少选择一种压缩算法。', true); return; }
  lock(true); $('export').disabled = true;
  status('正在将文件发送到本机…');
  const params = new URLSearchParams({ preset: $('preset').value, algorithms: algorithms.join(','), name: file.name });
  const options = { method: 'POST', body: file, headers: { 'Content-Type': 'application/wasm' } };
  try {
    job = await request(`/api/jobs?${params}`, options); render(job);
    while (job.status === 'running') {
      status(`正在压缩 ${names[job.current] || '模块'}，请稍候…`);
      await new Promise(resolve => setTimeout(resolve, 500));
      job = await request(`/api/jobs/${job.id}`); render(job);
    }
    if (job.status === 'failed') throw new Error(job.error);
    status('压缩完成，可以下载结果或导出 JSON。');
  } catch (error) { status(error.message, true); }
  finally { lock(false); }
};
$('export').onclick = () => {
  if (!job) return;
  const url = URL.createObjectURL(new Blob([JSON.stringify({ ...job, measuredAt: new Date().toISOString(), timing: 'Single-run Node wall-clock measurements; excludes upload and verification.' }, null, 2)], { type: 'application/json' }));
  const a = document.createElement('a'); a.href = url; a.download = `${job.name}.compression.json`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
};
try {
  const data = await request('/api/status');
  $('runtime').textContent = `${data.node} · 服务已连接`;
  lock(false); status('选择或拖入 .wasm 文件后即可开始。');
} catch (error) { $('runtime').textContent = '服务连接失败'; status(error.message, true); }

